#include <bitset>
#include <iostream>

int main() {
    std::bitset<4> b;
    b.set(); // All true: 1111

    // Conditional assignment
    int flag_on = 42; 
    int flag_off = 0;

    // b[0] = true (42 != 0)
    b.set(0, flag_on);

    // b[1] = false (0 == 0)
    b.set(1, flag_off);

    // b[2] = true (simple set)
    b.set(2);

    std::cout << "Bitset: " << b << "\n"; // Output: 1011
}
